/* @lc app=leetcode id=1803 lang=kotlin */ class Solution { fun cnt(a: IntArray, x: Int): Long = (0..15).sumOf { b -> if (x shr b and 1 == 0) 0L else a.asList().groupingBy { it shr b }.eachCount().let { f -> ((x shr b) xor 1).let { t -> if (t == 0) f.values.sumOf { it.toLong() * (it - 1) / 2 } else f.entries.sumOf { (k, c) -> c.toLong() * (f[k xor t] ?: 0) } / 2 } } } fun countPairs(nums: IntArray, low: Int, high: Int): Int = (cnt(nums, high + 1) - cnt(nums, low)).toInt() }